create table if not exists public.calendar_reward_config(day integer primary key check(day between 1 and 30),reward_type text not null check(reward_type in('fc','hero_chest','pet_egg')),amount_fc numeric not null default 0 check(amount_fc>=0),item_code text,title text not null,subtitle text,rarity_rates jsonb,enabled boolean not null default true,updated_at timestamptz not null default now());
insert into calendar_reward_config(day,reward_type,amount_fc,item_code,title,subtitle,rarity_rates) values
