on conflict(day) do update set reward_type=excluded.reward_type,amount_fc=excluded.amount_fc,item_code=excluded.item_code,title=excluded.title,subtitle=excluded.subtitle,rarity_rates=excluded.rarity_rates,updated_at=now();
create table if not exists public.daily_calendar_claims(id uuid primary key default gen_random_uuid(),user_id uuid not null references game_players(id),calendar_cycle text not null,day integer not null check(day between 1 and 30),reward_type text not null,reward_code text,amount_fc numeric not null default 0,idempotency_key text unique not null,claimed_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(user_id,calendar_cycle,day));
create table if not exists public.player_inventory(id uuid primary key default gen_random_uuid(),user_id uuid not null references game_players(id),item_type text not null,item_code text not null,quantity integer not null default 0 check(quantity>=0),updated_at timestamptz not null default now(),unique(user_id,item_type,item_code));
create table if not exists public.calendar_reward_history(id uuid primary key default gen_random_uuid(),user_id uuid not null references game_players(id),day integer not null,reward_type text not null,reward_code text,amount_fc numeric not null default 0,result_data jsonb,idempotency_key text unique not null,created_at timestamptz not null default now());
alter table calendar_reward_config enable row level security;alter table daily_calendar_claims enable row level security;alter table player_inventory enable row level security;alter table calendar_reward_history enable row level security;revoke all on calendar_reward_config,daily_calendar_claims,player_inventory,calendar_reward_history from anon,authenticated;

create or replace function public.get_calendar_dashboard(p_telegram_id bigint)returns jsonb language plpgsql security definer set search_path=public as $$declare u game_players%rowtype;cycle text;claimed int;last_at timestamptz;begin select*into u from game_players where telegram_id=p_telegram_id;if u.id is null then raise exception'PLAYER_NOT_FOUND';end if;select coalesce(max(calendar_cycle::int),1)::text into cycle from daily_calendar_claims where user_id=u.id;select count(*),max(claimed_at)into claimed,last_at from daily_calendar_claims where user_id=u.id and calendar_cycle=cycle;if claimed>=30 and last_at::date<current_date then cycle:=(cycle::int+1)::text;claimed:=0;last_at:=null;end if;return jsonb_build_object('cycle',cycle,'currentDay',claimed+1,'claimedDays',(select coalesce(jsonb_agg(day order by day),'[]')from daily_calendar_claims where user_id=u.id and calendar_cycle=cycle),'canClaim',claimed<30 and(last_at is null or last_at::date<current_date),'rewards',(select jsonb_agg(jsonb_build_object('day',day,'type',reward_type,'amountFc',amount_fc,'itemCode',item_code,'title',title,'subtitle',subtitle)order by day)from calendar_reward_config where enabled),'balance',u.forge_coins);end$$;

create or replace function public.claim_calendar_day(p_telegram_id bigint,p_day integer)returns jsonb language plpgsql security definer set search_path=public as $$declare u game_players%rowtype;d jsonb;cycle text;expected int;last_at timestamptz;r calendar_reward_config%rowtype;key text;egg uuid;inv_id uuid;begin select*into u from game_players where telegram_id=p_telegram_id for update;if u.id is null then raise exception'PLAYER_NOT_FOUND';end if;d:=get_calendar_dashboard(p_telegram_id);cycle:=d->>'cycle';expected:=(d->>'currentDay')::int;if not(d->>'canClaim')::boolean then raise exception'CALENDAR_ALREADY_CLAIMED_TODAY';end if;if p_day<>expected then raise exception'CALENDAR_DAY_LOCKED';end if;select*into r from calendar_reward_config where day=p_day and enabled for share;if r.day is null then raise exception'CALENDAR_REWARD_DISABLED';end if;if coalesce((r.rarity_rates->>'legendary')::numeric,0)>0 then raise exception'CALENDAR_LEGENDARY_FORBIDDEN';end if;if r.reward_type='pet_egg'and r.item_code not in('common-egg','rare-egg')then raise exception'CALENDAR_EGG_FORBIDDEN';end if;key:='calendar_claim:'||cycle||':'||u.id||':'||p_day;insert into daily_calendar_claims(user_id,calendar_cycle,day,reward_type,reward_code,amount_fc,idempotency_key)values(u.id,cycle,p_day,r.reward_type,r.item_code,r.amount_fc,key);if r.reward_type='fc'then update game_players set forge_coins=forge_coins+r.amount_fc,updated_at=now()where id=u.id;elsif r.reward_type='pet_egg'then select id into egg from pet_eggs where slug=r.item_code and is_enabled;if egg is null then raise exception'CALENDAR_EGG_NOT_FOUND';end if;insert into player_pet_inventory(user_id,item_type,item_id,quantity)values(u.id,'egg',egg,1)on conflict(user_id,item_type,(coalesce(item_id,'00000000-0000-0000-0000-000000000000'::uuid)))do update set quantity=player_pet_inventory.quantity+1,updated_at=now()returning id into inv_id;else insert into player_inventory(user_id,item_type,item_code,quantity)values(u.id,'hero_chest',r.item_code,1)on conflict(user_id,item_type,item_code)do update set quantity=player_inventory.quantity+1,updated_at=now()returning id into inv_id;end if;insert into calendar_reward_history(user_id,day,reward_type,reward_code,amount_fc,result_data,idempotency_key)values(u.id,p_day,r.reward_type,r.item_code,r.amount_fc,jsonb_build_object('inventoryItemId',inv_id),key);return jsonb_build_object('reward',jsonb_build_object('day',r.day,'type',r.reward_type,'amountFc',r.amount_fc,'itemCode',r.item_code,'title',r.title,'subtitle',r.subtitle),'balance',(select forge_coins from game_players where id=u.id),'inventoryItemId',inv_id,'dashboard',get_calendar_dashboard(p_telegram_id));end$$;
revoke all on function get_calendar_dashboard(bigint),claim_calendar_day(bigint,integer)from public,anon,authenticated;grant execute on function get_calendar_dashboard(bigint),claim_calendar_day(bigint,integer)to service_role;

alter table player_heroes add column if not exists base_atk numeric;
alter table player_heroes add column if not exists base_hp integer;
alter table player_heroes add column if not exists attribute_seed text;
create table if not exists public.calendar_chest_open_history(id uuid primary key default gen_random_uuid(),user_id uuid not null references game_players(id),inventory_item_id uuid not null references player_inventory(id),result_hero_id uuid not null references player_heroes(id),result_rarity text not null check(result_rarity in('common','uncommon','rare','epic')),idempotency_key text unique not null,created_at timestamptz not null default now());
alter table calendar_chest_open_history enable row level security;revoke all on calendar_chest_open_history from anon,authenticated;
create or replace function public.open_calendar_hero_chest(p_telegram_id bigint,p_inventory_item_id uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid;inv player_inventory%rowtype;rates jsonb;roll numeric;rar text;hero hero_catalog%rowtype;seed text;new_id uuid;basea numeric;baseh int;open_no int;key text;begin select id into u from game_players where telegram_id=p_telegram_id for update;if u is null then raise exception'PLAYER_NOT_FOUND';end if;select*into inv from player_inventory where id=p_inventory_item_id and user_id=u and item_type='hero_chest'for update;if inv.id is null or inv.quantity<1 then raise exception'CALENDAR_CHEST_NOT_OWNED';end if;select rarity_rates into rates from calendar_reward_config where item_code=inv.item_code limit 1;if rates is null or coalesce((rates->>'legendary')::numeric,0)<>0 then raise exception'INVALID_CALENDAR_CHEST_RATES';end if;select count(*)+1 into open_no from calendar_chest_open_history where inventory_item_id=inv.id;key:='calendar_chest_open:'||inv.id||':'||open_no;seed:=encode(digest(gen_random_bytes(32),'sha256'),'hex');roll:=(('x'||substr(seed,1,8))::bit(32)::bigint%1000000)/10000.0;rar:=case when roll<(rates->>'common')::numeric then'common'when roll<(rates->>'common')::numeric+(rates->>'uncommon')::numeric then'uncommon'when roll<(rates->>'common')::numeric+(rates->>'uncommon')::numeric+(rates->>'rare')::numeric then'rare'else'epic'end;if rar='legendary'then raise exception'CALENDAR_LEGENDARY_FORBIDDEN';end if;select*into hero from hero_catalog where enabled and rarity=rar order by hashtextextended(hero_key||seed,0)limit 1;if hero.hero_key is null then raise exception'NO_ELIGIBLE_CALENDAR_HERO';end if;basea:=round((case rar when'epic'then 2.395 when'rare'then 2.165 when'uncommon'then 1.975 else 1.875 end)*(.95+(('x'||substr(seed,9,4))::bit(16)::int%101)/1000.0),3);baseh:=round((case rar when'epic'then 220 when'rare'then 170 when'uncommon'then 130 else 100 end)*(.95+(('x'||substr(seed,13,4))::bit(16)::int%101)/1000.0));update player_inventory set quantity=quantity-1,updated_at=now()where id=inv.id;insert into player_heroes(user_id,hero_key,name,rarity,level,image,base_atk,base_hp,attribute_seed)values(u,hero.hero_key,hero.name,rar,1,hero.image,basea,baseh,seed)returning id into new_id;insert into calendar_chest_open_history(user_id,inventory_item_id,result_hero_id,result_rarity,idempotency_key)values(u,inv.id,new_id,rar,key);return jsonb_build_object('hero',jsonb_build_object('id',new_id,'name',hero.name,'image',hero.image,'rarity',rar,'level',1,'baseAtk',basea,'baseHp',baseh));end$$;
revoke all on function open_calendar_hero_chest(bigint,uuid)from public,anon,authenticated;grant execute on function open_calendar_hero_chest(bigint,uuid)to service_role;
